return [{ json: {
  theme: 'friendly ocean animals',
  audience: 'ages 4-8',
  page_count: 20,
  trim_size: '8.5x11',
  original_confirmation: true,
  output_path: './kdp-brief.md'
} }];

const j = $input.first().json;
const e = [];
if (!j.theme || !j.theme.trim()) e.push('theme required (original theme, not a competitor book)');
if (j.original_confirmation !== true) e.push('original_confirmation must be true: only original artwork, no cloning of an existing book');
if (!Number.isInteger(j.page_count) || j.page_count < 1 || j.page_count > 120) e.push('page_count must be 1-120');
if (e.length) throw new Error('Blocked: ' + e.join('; '));
const subjects = ['scene', 'close-up', 'pattern', 'action pose', 'habitat'];
const pages = [];
for (let i = 1; i <= j.page_count; i++) {
  pages.push('Page ' + i + ' [' + subjects[(i-1) % subjects.length] + ']: bold clean outlines, no shading, thick lines, white background, ' + j.theme + ', suitable for ' + (j.audience||'kids'));
}
const md = ['# Original coloring book brief', '', '- Theme: ' + j.theme, '- Audience: ' + (j.audience||''), '- Trim size: ' + (j.trim_size||'8.5x11'), '- Pages: ' + j.page_count, '', '## Page prompt list (for your image tool - MANUAL)', ...pages.map(p => '- ' + p), '', '## KDP manuscript checklist (MANUAL upload)', '- [ ] Interior PDF at correct trim size + bleed', '- [ ] One coloring image per page, single-sided', '- [ ] Original cover (front/back/spine)', '- [ ] Title, subtitle, 7 keywords, 2 categories', '- [ ] Confirm all art is original / owned', '- [ ] Set price + territories in KDP', '', '> Image generation and KDP publishing are manual handoffs. No API is called by this workflow.'].join('\n');
return [{ json: { output_path: j.output_path || './kdp-brief.md', markdown: md } }];

const sourceId="DcQzhCghRZI";
const sourceUrl="https://www.instagram.com/xanderdoesai/reel/DcQzhCghRZI/";
const variant='USER_STACK';
const seen=new Set();
const hash=s=>{let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return (h>>>0).toString(16).padStart(8,'0');};
return $input.all().map(({json:j},i)=>{
  const recordKey=String(j.row_id||j.clip_id||j.note_id||j.fileName||j.output_path||j.title||i);
  const idempotencyKey=hash(sourceId+'|'+recordKey);
  if(seen.has(idempotencyKey)) throw new Error('Duplicate output in one execution: '+idempotencyKey);
  seen.add(idempotencyKey);
  return {json:{...j,source_provenance:{source_id:sourceId,source_url:sourceUrl,variant},idempotency_key:idempotencyKey,review_status:'needs_human_review',review_notes:Array.isArray(j.review_notes)?j.review_notes:[],external_actions_enabled:false}};
});
